// ---------------------------------------------------------------------------
// --- a macro with an empty name
//     expands without calling a function on the block

export type TTextBlock = {
	type: 'text'
	firstLine: string
	lContent: TBlock[]
	}

export type TMacroBlock = {
	type: 'macro'
	name: string
	args: string
	lContent: TBlock[]
	}

export type TBlock = TTextBlock | TMacroBlock

// ---------------------------------------------------------------------------

export type TMacroFunc = (
		block: string,
		args?: string
		) => string

// --- In a TMacroLib, the key '#preproc'
//     is a function to preprocess the entire output

export type TMacroLib = hashof<TMacroFunc>

export const isMacroLib = (x: unknown): x is TMacroLib => {

	if (!isHash(x)) {
		return false
	}
	for (const [key,func] of Object.entries(x)) {
		if (!isFunction(func)) {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------

export const expand = (
		lContent: TBlock[],
		hMacros: TMacroLib
		): string => {

	const lParts = mkArray(lContent, function*(x) {
		switch(x.type) {
			case 'text': {
				yield x.firstLine
				if (nonEmpty(x.lContent)) {
					yield indented(expand(x.lContent, hMacros))
				};break;
			}
			case 'macro': {
				const func = hMacros[x.name]
				yield func(expand(x.lContent, hMacros), x.args);break;
			}
		}
	})

	return toBlock(lParts)
}

// ---------------------------------------------------------------------------
// ASYNC

export const strApplyMacros = async (
		text: string,
		hMacros: TMacroLib
		): AutoPromise<string> => {

	const lBlocks: TBlock[] = await parseText('macros', text)
	const block =  toBlock(expand(lBlocks, hMacros))
	const func = hMacros['#preproc']
	return defined(func) ? func(block) : block
}

// ---------------------------------------------------------------------------
// ASYNC

export const fileApplyMacros = async (
		path: string,
		hMacros: TMacroLib
		): AutoPromise<string> => {

	const {ext} = parsePath(path)
	assert(defined(ext) && ext.startsWith('.$'),
		`Not a macro file: ${path}`)
	const file = new CReadableFile(path)
	const hMetaData = await file.metaData()
	const text = await file.getContents()
	return await strApplyMacros(text, hMacros)
}

// ---------------------------------------------------------------------------

export class CMacroCompiler extends CFileHandler {

	ext: string
	outext: string
	hLib: TMacroLib

	constructor(
			ext1: string,
			hLib1: TMacroLib
			) {

		super()

		this.ext = ext1;

		this.hLib = hLib1;
		const lMatches = this.ext.match(/^\.\$([A-Za-z][A-Za-z0-9]*)$/)
		if (defined(lMatches)) {
			this.outext = '.' + lMatches[1]
		}
		else {
			croak(`Bad ext: ${this.ext}`)
		}
	}

	// ..........................................................

	get op() {

		return 'doCompileMacroFile'
	}

	// ..........................................................

	async canHandle(
			path: string,
			hOptions: hash = {}
			) {

		return path.endsWith(this.ext)
	}

	// ..........................................................

	override allOutPaths(
			path: string,
			hOptions: hash = {}
			): string[] {

		return [withExt(path, this.outext)]
	}

	// ..........................................................
	// ASYNC

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		type opt = {
			force: boolean
			trace: boolean
			}
		const {force, trace} = getOptions<opt>(hOptions, {
			force: false,
			trace: false
			})

		const destPath = this.allOutPaths(path, hOptions)[0]
		try {
			const input = await Deno.readTextFile(path)
			const output = await strApplyMacros(input, this.hLib)
			await Deno.writeTextFile(destPath, output)
			return {
				success: true,
				stdout: output,
				timeTaken: -1
				}
		}

		catch (err) {
			const errMsg = `MACRO FAILED: ${toRelPath(path)} - ${getErrStr(err)}`
			DBG(errMsg)
			return {
				success: false,
				stderr: errMsg,
				timeTaken: -1
				}
		}
	}
}

